using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading;using System.Threading.Tasks;using System.Web.Script.Serialization;using ReplierDesktop;
public static class ContextActualChecks {
 public sealed class Window {public string id,time,text;}
 public sealed class Candidate {public string text;public int score;}
 public sealed class Document {public string title;public Window[] windows;public Candidate[] candidates;}
 public static int Main(string[] args){try{string root=args[0];var json=new JavaScriptSerializer{MaxJsonLength=16*1024*1024};string dir=Path.Combine(root,"extension/data/replier-grounded-checks");var doc=json.Deserialize<Document>(File.ReadAllText(Path.Combine(dir,"context-input-I1xGsYtr09c.json")));var video=new Video{Id="I1xGsYtr09c",Title=doc.title,Channel="김성회의 G식백과"};var content=new ContentStore(Path.Combine(root,"extension/data/replier/content")).Load(video.Id);var evidence=CommentService.Evidence(content,video.Title);
 foreach(var w in doc.windows){if(!evidence.ContainsKey(w.id)||!ContextGuidance.HasQuote(evidence[w.id].Text,w.text))throw new Exception("Stored source differs from exact report: "+w.id);}Console.WriteLine("SOURCE exact report windows matched cached production evidence");
 doc.candidates=doc.candidates.Take(3).ToArray();var rows=doc.candidates.Select(c=>new CommentSuggestion{Text=c.text,CueId=evidence.Keys.First(),Material="{\"context_version\":2}"}).ToArray();var runtimes=DualCommentService.Models.ToDictionary(n=>n,n=>new LocalModel(Path.Combine(root,"extension/.runtime/replier-llm"),n));var trace=new List<object>();int calls=0;
 Func<string,Func<object,CancellationToken,Task<string>>> sender=name=>async(body,token)=>{calls++;Console.WriteLine("CALL "+calls+" "+name);string raw=await runtimes[name].Chat(body,token).ConfigureAwait(false);trace.Add(new{model=name,response=SceneMaterial.Json(raw)});File.WriteAllText(Path.Combine(dir,"context-role-trace-I1xGsYtr09c.json"),json.Serialize(trace));return raw;};
 try{var scoring=new CombinedFitScoring(new FitScoring(runtimes[DualCommentService.Models[0]],sender(DualCommentService.Models[0])),new FitScoring(runtimes[DualCommentService.Models[1]],sender(DualCommentService.Models[1])),runtimes[DualCommentService.Models[0]].Unload);scoring.Evaluate(video,content,rows,CancellationToken.None).GetAwaiter().GetResult();}finally{foreach(var m in runtimes.Values.Reverse())m.Dispose();}
 bool pass=rows[0].FitScore<rows[1].FitScore&&rows[1].FitEligible==true&&rows[2].FitEligible==true;var best=rows.Where(c=>c.FitEligible==true).OrderByDescending(c=>c.FitScore).FirstOrDefault();
 File.WriteAllText(Path.Combine(dir,"context-rating-role-I1xGsYtr09c.json"),json.Serialize(new{video=video,before=doc.candidates,after=rows,best=best,trace=trace,pass=pass,new_comments_generated=false,original_evidence_verified=true,model_calls=calls}));
 for(int i=0;i<rows.Length;i++){Console.WriteLine("RESULT "+doc.candidates[i].score+" -> "+rows[i].FitScore+" eligible="+rows[i].FitEligible+" "+rows[i].Text);Console.WriteLine(rows[i].FitReason);}Console.WriteLine(pass?"PASS existing-candidate context contrast":"FAIL inspect semantic contrast");return pass?0:1;
 }catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
